def event_description(key, source, note=""):
    importance, explanation, impact = EVENT_INFO[key]
    parts = [
        f"חשיבות למסחר: {importance}",
        "",
        explanation,
        "",
        f"למה זה חשוב למסחר? {impact}",
        "",
        "דירוג החשיבות הוא הערכה כללית בלבד; עוצמת התגובה בפועל אינה ידועה מראש.",
        f"מקור: {source}",
    ]
    if note:
        parts.extend(["", note])
    return "\n".join(parts)
